schema_ddl:
CREATE TABLE clienti (
    id INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE conti (
    id INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    saldo_conto NUMERIC(12,2) NOT NULL CHECK (saldo_conto >= 0),
    data_apertura DATE NOT NULL
);

CREATE TABLE movimenti_conto (
    id INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    conto_id INT NOT NULL REFERENCES conti(id),
    saldo_movimento NUMERIC(12,2) NOT NULL,
    data_movimento DATE NOT NULL,
    descrizione TEXT
);

CREATE TABLE conti_movimenti (
    conto_id INT NOT NULL REFERENCES conti(id),
    movimento_id INT NOT NULL REFERENCES movimenti_conto(id),
    PRIMARY KEY (conto_id, movimento_id)
);

CREATE TABLE transazioni (
    id INT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    data_transazione TIMESTAMP NOT NULL DEFAULT NOW(),
    importo NUMERIC(12,2) NOT NULL CHECK (importo >= 0),
    tipo_transazione TEXT NOT NULL CHECK (tipo_transazione IN ('DEPOSITO', 'PRELIEVO', 'TRANSFERT'))
);
